import pyomo.environ as pyo

DATA = {
    "routes": ["X", "Y"],
    "cost": {"X": 10, "Y": 20},
    "upper_bound": {"X": 70, "Y": 50},
    "total_ships_limit": 100,
    "demand_coeff": {"X": 2, "Y": 1},
    "demand_min": 60,
    "balance_limit": 30,
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.ROUTES = pyo.Set(initialize=d["routes"])

    def _ub(m, r):
        return (0, d["upper_bound"][r])

    model.ships = pyo.Var(
        model.ROUTES,
        within=pyo.NonNegativeIntegers,
        bounds=_ub,
    )

    def _obj(m):
        return sum(d["cost"][r] * m.ships[r] for r in m.ROUTES)

    model.obj = pyo.Objective(rule=_obj, sense=pyo.minimize)

    def _total_limit(m):
        return sum(m.ships[r] for r in m.ROUTES) <= d["total_ships_limit"]

    model.total_ships_limit = pyo.Constraint(rule=_total_limit)

    def _demand(m):
        return sum(d["demand_coeff"][r] * m.ships[r] for r in m.ROUTES) >= d["demand_min"]

    model.demand = pyo.Constraint(rule=_demand)

    def _balance_pos(m):
        return m.ships["X"] - m.ships["Y"] <= d["balance_limit"]

    model.balance_pos = pyo.Constraint(rule=_balance_pos)

    def _balance_neg(m):
        return m.ships["Y"] - m.ships["X"] <= d["balance_limit"]

    model.balance_neg = pyo.Constraint(rule=_balance_neg)

    return model

import pyomo.environ as pyo

DATA = {
    "ROUTES": ["X", "Y"],
    "cost": {"X": 10, "Y": 20},
    "fleet_limit": 100,
    "demand_coef_X": 2,
    "demand_coef_Y": 1,
    "demand_min": 60,
    "balance_max": 30,
    "ub_X": 70,
    "ub_Y": 50,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.ROUTES = pyo.Set(initialize=d["ROUTES"])

    def var_bounds(m, r):
        return (0, d["ub_" + r])

    model.x = pyo.Var(
        model.ROUTES,
        domain=pyo.NonNegativeIntegers,
        bounds=var_bounds,
    )

    def cost_sum(m):
        return sum(d["cost"][r] * m.x[r] for r in m.ROUTES)

    model.obj = pyo.Objective(expr=cost_sum, sense=pyo.minimize)

    def fleet_rule(m):
        return sum(m.x[r] for r in m.ROUTES) <= d["fleet_limit"]

    model.fleet_limit_constraint = pyo.Constraint(rule=fleet_rule)

    def demand_rule(m):
        return (
            d["demand_coef_X"] * m.x["X"]
            + d["demand_coef_Y"] * m.x["Y"]
            >= d["demand_min"]
        )

    model.demand_constraint = pyo.Constraint(rule=demand_rule)

    def balance_XY_rule(m):
        return m.x["X"] - m.x["Y"] <= d["balance_max"]

    model.balance_XY_constraint = pyo.Constraint(rule=balance_XY_rule)

    def balance_YX_rule(m):
        return m.x["Y"] - m.x["X"] <= d["balance_max"]

    model.balance_YX_constraint = pyo.Constraint(rule=balance_YX_rule)

    return model


